<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/paystack.php';$raw=file_get_contents('php://input')?:'';$signature=$_SERVER['HTTP_X_PAYSTACK_SIGNATURE']??'';if(!paystack_signature_valid($raw,$signature)){http_response_code(401);exit('Invalid signature');}$event=json_decode($raw,true);$reference=(string)($event['data']['reference']??'');if($reference===''||($event['event']??'')!=='charge.success'){http_response_code(200);exit('Ignored');}$q=$db->prepare('SELECT * FROM invoice_payments WHERE reference=? LIMIT 1');$q->execute([$reference]);$payment=$q->fetch();if(!$payment){http_response_code(200);exit('Unknown reference');}if($payment['status']==='successful'){http_response_code(200);exit('Already processed');}$db->beginTransaction();try{$db->prepare("UPDATE invoice_payments SET status='successful',gateway_transaction_id=?,paid_at=NOW(),metadata=? WHERE id=?")->execute([(string)($event['data']['id']??''),$raw,$payment['id']]);$sum=$db->prepare("SELECT COALESCE(SUM(amount),0) FROM invoice_payments WHERE invoice_id=? AND status='successful'");$sum->execute([$payment['invoice_id']]);$paid=(float)$sum->fetchColumn();$inv=$db->prepare('SELECT total FROM invoices WHERE id=?');$inv->execute([$payment['invoice_id']]);$total=(float)$inv->fetchColumn();$balance=max(0,$total-$paid);$status=$balance<=0?'paid':'partially_paid';$db->prepare('UPDATE invoices SET amount_paid=?,balance_due=?,status=? WHERE id=?')->execute([$paid,$balance,$status,$payment['invoice_id']]);$db->prepare('INSERT INTO invoice_events (invoice_id,event_type,description) VALUES (?,?,?)')->execute([$payment['invoice_id'],'payment_success','Paystack webhook confirmed '.$reference]);$db->prepare('INSERT INTO lead_activities (lead_id,activity_type,subject,description) VALUES (?,?,?,?)')->execute([$payment['lead_id'],'payment','Payment received','Paystack webhook confirmed payment '.$reference]);$db->commit();http_response_code(200);echo 'OK';}catch(Throwable $e){$db->rollBack();http_response_code(500);echo 'Webhook processing failed';}
